select 'care', 'NeoHealth', 'NeoHealth', 'دبي', 'برشا هايتس (تيكوم)', '+971 4 449 0456', 'https://neohealth.ae', null, 'مزوّد خدمات رعاية صحية منزلية في دبي يشمل التمريض ورعاية المسنين والأطفال حديثي الولادة.', 'https://neohealth.ae/how-dha-licensed-home-nurses-improve-patient-recovery', 'نيو هيلث مزوّد رعاية صحية منزلية في دبي يقدّم رعاية المواليد والأطفال والمسنين والرعاية التلطيفية والعلاج الطبيعي. يذكر الموقع أن ممرضيه معتمدون من هيئة الصحة بدبي وأن فريقه متاح عند الطلب في أنحاء دبي.', 'https://neohealth.ae/uploads/image/setting/1700823017.svg', null, 'الطابق العاشر، مكتب 1005، برج الشفار 1، برشا هايتس، تيكوم، دبي', null, array['رعاية المواليد', 'رعاية المسنين', 'الرعاية التلطيفية', 'العلاج الطبيعي في المنزل', 'طبيب عند الطلب']::text[], 'يذكر الموقع أن لدى الفريق أكثر من 30 عامًا من الخبرة المجمّعة في إدارة الرعاية الصحية ويتحدث لغات متعددة.', true
where not exists (select 1 from public.service_providers where category = 'care' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('NeoHealth'));
