select 'care', 'Bayti Home Healthcare', 'Bayti Home Healthcare', 'أبوظبي', 'شارع السلام – الفلاح', '+971 800 9955', 'https://baytihealth.com', 2013, 'مزوّد رعاية صحية منزلية مقرّه أبوظبي يقدّم التمريض ورعاية المسنين وجليسات الأطفال.', 'https://baytihealth.com/babysitting-services/', 'بيتي للرعاية الصحية المنزلية تقدّم الرعاية الطبية والتمريضية في المنازل منذ 2013 ولها مكاتب في أبوظبي ودبي وعجمان والظفرة. يذكر الموقع أنها مزوّد مرخّص وحاصل على اعتماد JCI، وأن ممرضيها مرخّصون من دائرة الصحة أبوظبي وهيئة الصحة بدبي.', 'https://baytihealth.com/assets/img/Brand/bayti-logo-small.png', null, 'مبنى أمانة، الطابق الأول، شارع السلام – الفلاح، أبوظبي', 'https://maps.app.goo.gl/EpNt6Pgvn95H1kt29', array['التمريض المنزلي', 'رعاية المسنين في المنزل', 'خدمات جليسات الأطفال', 'خدمات مقدّمي الرعاية', 'العلاج التنفسي']::text[], null, true
