select 'domestic', 'Imdad Center for Domestic Workers Services L.L.C', 'Imdad Center for Domestic Workers Services L.L.C', 'دبي', 'رأس الخور الصناعية 1', '+971 4 320 0961', 'https://imdadcenter.ae/', null, 'مركز خدمات عمالة مساعدة (تدبير) في دبي يقدم الاستقدام والتأشيرات والتوظيف المؤقت.', 'https://imdadcenter.ae/', 'يصف المركز نفسه بأنه مركز خدمات عمالة مساعدة مرخص من وزارة الموارد البشرية والتوطين ضمن منظومة تدبير في دبي. يتولى الاستقدام وإجراءات التأشيرة وتدريب العمالة، إضافة إلى خدمات الطباعة الحكومية والتجديد والاستبدال. يذكر أنه يغطي 19 فئة من العمالة المساعدة.', 'https://imdadcenter.ae/wp-content/uploads/2025/06/imdad_logo.webp', 'info@imdadhr.ae', 'مكتب رقم 1، مبنى مالك عامر إبراهيم، منطقة رأس الخور الصناعية 1، دبي', 'https://maps.app.goo.gl/2ogck8zdAf8pyXUGA', array['الاستقدام مع ضمان 180 يومًا', 'التوظيف المؤقت في اليوم نفسه', 'عمالة مقيمة بدوام كامل', 'تأشيرة العمالة المساعدة لمدة سنتين', 'خدمات طباعة تدبير والهوية والتأمين']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Imdad Center for Domestic Workers Services L.L.C'));
