select 'domestic', 'Mountain Gate L.L.C (Mountain Gate Center for Domestic Workers Services)', 'Mountain Gate L.L.C (Mountain Gate Center for Domestic Workers Services)', 'دبي', 'بورسعيد', '+971 4 401 8888', 'https://maids.mgtadbeer.com/', 2018, 'مركز في دبي لتوفير الخادمات والمربيات والسائقين والطهاة بنظام تدبير والكفالة المباشرة.', 'https://maids.mgtadbeer.com/', 'تذكر الشركة أنها تخدم العائلات في الإمارات منذ عام 2018 وأنها مسجلة ومعتمدة من وزارة الموارد البشرية والتوطين. تتولى الاستقدام والتوثيق والتدريب والدعم المستمر، وتذكر أن سائقيها يحملون رخص هيئة الطرق والمواصلات.', 'https://maids.mgtadbeer.com/public/logo.png', 'info@mgtadbeer.com', 'بورسعيد، دبي', 'https://maps.app.goo.gl/EyaBYmtD2ceGeskm7', array['الكفالة المباشرة', 'كفالة تدبير', 'باقات شهرية وبالساعة', 'خادمات ومربيات وطهاة', 'سائقون خاصون']::text[], null, true
