select 'domestic', 'Al Safwa Tadbeer (Al Safwa Domestic Workers Services L.L.C)', 'Al Safwa Tadbeer (Al Safwa Domestic Workers Services L.L.C)', 'دبي', null, '+971 4 252 0414', 'https://www.tadbeeralsafwa.ae/', null, 'مركز في دبي لاستقدام العمالة المساعدة مرخص من وزارة الموارد البشرية والتوطين.', 'https://www.tadbeeralsafwa.ae/', 'يصف المركز نفسه بأنه مركز لاستقدام العمالة المساعدة مرخص من وزارة الموارد البشرية والتوطين. يقدم باقات تدبير شهرية وخدمات طباعة المعاملات الحكومية، ويذكر توفير 19 فئة من العمالة المساعدة من جنسيات منها الفلبين وغانا وإندونيسيا.', 'https://tadbeeralsafwa.ae/web/image/website/1/logo?unique=170d611', 'info@tadbeeralsafwa.ae', 'دبي', null, array['خدمات العمالة المساعدة', 'باقات تدبير الشهرية', 'طباعة المعاملات الحكومية', 'خادمات وسائقون وطهاة وبستانيون']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Safwa Tadbeer (Al Safwa Domestic Workers Services L.L.C)'));
