select 'movers', 'Leader Relocations LLC', 'Leader Relocations LLC', 'دبي', 'Dubai Investment Park', '+971 800 532337', 'https://www.leaderrelocations.com/', 1991, 'شركة نقل وانتقال في دبي تقدم النقل المحلي والدولي والتخزين ونقل المكاتب منذ 1991.', 'https://www.leaderrelocations.com/', 'تأسست Leader Relocations LLC عام 1991 وتقدم خدمات النقل الدولي والمحلي ونقل المكاتب والشركات. وتوفر تخزينًا قصير وطويل الأمد بما فيه التخزين المكيّف وتخزين السيارات. وتذكر أنها مرخصة ومؤمَّنة وعضو في شبكة وكلاء IAM.', 'https://www.leaderrelocations.com/wp-content/uploads/2024/02/Leader-Full-logo-no-bg-e1744870309220.webp', 'info@leaderrelocations.com', 'WN-3، مجمع دبي للاستثمار، ص.ب 16327، دبي، الإمارات', null, array['النقل الدولي', 'نقل المنازل محليًا وداخل الخليج', 'نقل المكاتب وتقنية المعلومات', 'التخزين المكيّف وتخزين السيارات', 'شحن السيارات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Leader Relocations LLC'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'movers', 'ISS Relocations', 'ISS Relocations', 'دبي', 'Al Quoz Industrial Area 1', '+971 4 234 8100', 'https://iss-relocations.com/', null, 'شركة نقل في دبي تقدم نقل المنازل والمكاتب والنقل الدولي والتغليف والتخزين والتخليص الجمركي.', 'https://iss-relocations.com/', 'تقدم ISS Relocations نقل المنازل والمكاتب والانتقال الدولي مع التغليف والتخزين والتخليص الجمركي. وتذكر أن نشاطها بدأ عام 1996 باسم Mac Movers ضمن Mackenzie Logistics. وتعلن أنها معتمدة من FIDI وحاصلة على ISO 9001 وISO 14001، ولها مكتب في أبوظبي أيضًا.', 'https://iss-relocations.com/wp-content/uploads/2025/05/ISS-Relocations-Best-Moving-Services-in-Dubai.svg', 'uae@iss-relocations.com', 'مجمع UPS، مستودع B2-14، منطقة القوز الصناعية 1، ص.ب 122511، دبي', 'https://share.google/28QZhYZcy0abn9d8K', array['نقل المنازل والمكاتب', 'الانتقال الدولي والشحن', 'التغليف والتخزين', 'شحن السيارات ونقل الحيوانات الأليفة', 'إدارة السجلات وتجهيز الفنادق']::text[], 'تذكر الشركة أن موظفيها مدرَّبون وخضعوا لفحص الخلفية.', true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('ISS Relocations'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'movers', 'E-Movers LLC', 'E-Movers LLC', 'دبي', null, '+971 4 341 7042', 'https://emoversuae.com/', 2003, 'شركة نقل تعمل منذ 2003 في دبي والشارقة وأبوظبي لنقل المنازل والمكاتب والنقل الدولي والتخزين.', 'https://emoversuae.com/', 'تعمل E-Movers منذ 2003 في نقل المنازل والمكاتب والانتقال الدولي وتركيب الأثاث. وتوفر تخزينًا قصير وطويل الأمد في منشأة تزيد على 100,000 قدم مربعة. ولها رقم هاتف في أبوظبي إلى جانب دبي.', 'https://emoversuae.com/wp-content/themes/emovers-revamp/images/emove-logo-new-v1.png', 'mail@emoversuae.com', null, null, array['نقل المنازل والمكاتب', 'الانتقال الدولي', 'التخزين', 'نقل الأعمال الفنية', 'خدمة عاملات تغليف']::text[], 'تذكر الشركة أن لديها أكثر من 500 موظف وأكثر من 100 مركبة.', true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('E-Movers LLC'));
