select 'movers', 'On The Move', 'On The Move', 'دبي', 'Jebel Ali Industrial Area 2', '+971 4 884 7705', 'https://onthemove.ae/', null, 'شركة نقل في جبل علي بدبي تقدم النقل داخل الإمارات والنقل الدولي والتخزين ونقل الحيوانات الأليفة.', 'https://onthemove.ae/', 'On The Move شركة نقل تديرها إدارة بريطانية ومقرها جبل علي في دبي. تقدم النقل داخل الإمارات والنقل الدولي ونقل الحيوانات الأليفة. وتملك منشأة تخزين بمساحة 6,000 قدم مربعة في منطقة جبل علي الصناعية.', 'https://onthemove.ae/wp-content/uploads/2019/01/On-The-Move-Logo.jpg', 'enquiries@onthemove.ae', 'مستودع 4، منطقة جبل علي الصناعية 2، دبي', null, array['النقل داخل الإمارات', 'النقل الدولي', 'التخزين', 'نقل الحيوانات الأليفة']::text[], 'تديرها إدارة بريطانية مع مستشاري نقل يقدمون خدمة فردية.', true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('On The Move'));
