select 'engineering', 'X-Architects', 'X-Architects', 'دبي', 'شارع الشيخ زايد', '+97143884611', 'https://x-architects.com', null, 'مكتب تصميم معماري مقره دبي يعمل على مشاريع ثقافية ودينية وسكنية ومخططات عامة.', 'https://x-architects.com/contact-us/', 'مكتب معماري مقره الرئيسي في دبي وله مكاتب في الرياض وأبوظبي. يتبع نهجًا تصميميًا قائمًا على السرد ومراعاة السياق، مع مرحلة مفاهيمية مبكرة تتحول فيها الكتل النحتية إلى هوية بصرية للمشروع.', 'https://x-architects.com/wp-content/uploads/2025/02/logo-png.png', 'info@x-architects.com', 'مبنى الشيخ سهيل، مكتب 01، شارع الشيخ زايد، دبي', null, array['سفارة الإمارات', 'مقر أبوظبي للإعلام', 'أبحاث الإسكان الوطني', 'مخططات عامة ومشاريع ثقافية ودينية']::text[], 'فريق دولي يعمل عبر عدة مكاتب.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('X-Architects'));
