select 'engineering', 'Al Hashemi Planners, Architects, Engineers', 'Al Hashemi Planners, Architects, Engineers', 'دبي', 'الوحيدة', '+97142684466', 'https://www.alhashemi.ae', 1983, 'مكتب استشارات هندسية في دبي يقدم التخطيط العمراني والتصميم المعماري والهندسي والإشراف على المواقع.', 'https://www.alhashemi.ae/the-company', 'مكتب استشاري محلي مقره دبي تأسس في الإمارات عام 1983. يقدم التخطيط الرئيسي والتصميم المعماري والهندسة والإشراف على المواقع لفلل ومبانٍ تجارية وسكنية مرتفعة وفنادق ومنشآت صناعية وصحية. يذكر أنه أول شركة محلية في الإمارات تُدخل تقنية الشد اللاحق بالتعاون مع مينهاردت.', 'https://static.wixstatic.com/media/bd83c4_907e9ba01fe54559a8c4a480238db5fb~mv2.png', 'info@alhashemi.ae', 'مكتب M-05، مبنى دار النهضة، شارع الوحيدة، ص.ب 13313، دبي', null, array['مسجد مصبح بن راشد الفطان', 'فلل فاخرة', 'أبراج سكنية وتجارية', 'فنادق', 'منشآت صحية وتعليمية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Hashemi Planners, Architects, Engineers'));
