select 'immigration', 'DM Immigration Consultants', 'DM Immigration Consultants', 'أبوظبي', 'شارع السلام', '+97124914919', 'https://dm-consultant.com', null, 'مكتب استشارات هجرة وتأشيرات في مبنى السلام على شارع السلام بأبوظبي.', 'https://dm-consultant.com/home/abu-dhabi', 'تقدّم دي إم للاستشارات خدمات الهجرة إلى كندا والولايات المتحدة والمملكة المتحدة وأستراليا ونيوزيلندا، ومعالجة تأشيرات الإقامة الدائمة والدراسة والاستثمار، وخدمات ما قبل الوصول وما بعده.', null, null, 'مكتب 1802، مبنى السلام HQ، شارع السلام، أبوظبي', null, array['الهجرة إلى كندا', 'تأشيرات الإقامة الدائمة', 'تأشيرات الأعمال والمستثمرين', 'تأشيرات الدراسة', 'خدمات ما قبل الوصول وما بعده']::text[], 'أسسها فيديشا دربان وتشيتان كومبهار، وتذكر أن لديها أكثر من 300 خبير هجرة.', true
