select 'recruitment', 'NADIA Global', 'NADIA Global', 'دبي', 'أبراج بحيرات جميرا', '+971 4 447 2599', 'https://www.nadiaglobal.com', 1983, 'وكالة توظيف ومعهد تدريب مؤسسي يخدم الإمارات والخليج منذ 1983، ولها مكتب في أبراج بحيرات جميرا بدبي.', 'https://www.nadiaglobal.com/get-in-touch/', 'ناديا جلوبال وكالة توظيف ومعهد تدريب مؤسسي تأسس عام 1983 ويخدم الإمارات ودول الخليج. تقدم خدمات التوظيف الدائم والمؤقت والتوظيف بالجملة والبحث عن التنفيذيين والتعهيد، إضافة إلى برامج التوطين والتدريب المؤسسي، ولها مكاتب في دبي وأبوظبي والرياض.', 'https://www.nadiaglobal.com/assets/img/Nadia-global-logo.png', 'contact@nadiaglobal.com', 'الطابق 36، ون ليك بلازا، المجموعة T، أبراج بحيرات جميرا، دبي', null, array['التوظيف الدائم والمؤقت', 'البحث عن كبار التنفيذيين', 'تعهيد الموظفين والرواتب', 'خدمات التوطين', 'التدريب المؤسسي']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'recruitment' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('NADIA Global'));
