select 'pets', 'Blue Sky Pet Relocation', 'Blue Sky Pet Relocation', 'دبي', null, '+971545067276', 'https://blueskypetrelocation.com/', null, 'شركة في دبي متخصصة في نقل الحيوانات الأليفة من الإمارات وإليها، وعضو في جمعية IPATA.', 'https://blueskypetrelocation.com/', 'تقدّم بلو سكاي خدمات تصدير واستيراد الحيوانات الأليفة من الإمارات وإليها مع إنجاز التصاريح والشهادات الصحية والتنسيق البيطري واللوجستي. وتذكر أنها عضو في الجمعية الدولية لنقل الحيوانات الأليفة (IPATA)، وأنها قسم تابع لعيادة بلو أويسس البيطرية.', 'https://blueskypetrelocation.com/wp-content/uploads/2020/08/Logo-bluesky-updated-header.png', 'info@blueskypetrelocation.com', null, null, array['تصدير الحيوانات الأليفة من الإمارات', 'استيراد الحيوانات الأليفة إلى الإمارات', 'خدمة تاكسي الحيوانات الأليفة', 'خدمات نقل كبار التنفيذيين بالشراكة مع شركات التنقل']::text[], 'يضم الفريق أخصائيي نقل حيوانات أليفة بينهم مديرة بخبرة تزيد على 10 سنوات.', true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Blue Sky Pet Relocation'));
