select 'pets', 'ABVC - Al Barsha Veterinary Clinic (Kennels & Cattery / Pet Travel)', 'ABVC - Al Barsha Veterinary Clinic (Kennels & Cattery / Pet Travel)', 'دبي', 'البرشاء 1', '+97143408601', 'https://abvc.ae/', null, 'عيادة بيطرية في البرشاء بدبي تقدم إيواء القطط والكلاب وخدمات سفر ونقل الحيوانات الأليفة.', 'https://abvc.ae/services/pet-travel-information/', 'عيادة البرشاء البيطرية (ABVC) تقدم خدمات بيطرية تشمل الطوارئ والجراحة والصيدلية، إلى جانب فندق للكلاب والقطط. ولديها قسم لسفر ونقل القطط والكلاب من دبي وإليها، وهي مدرجة عضوًا في جمعية IPATA.', 'https://abvc.ae/wp-content/uploads/2020/09/logonew.png', 'travel@abvc.ae', 'عيادة البرشاء البيطرية ذ.م.م، البرشاء 1، دبي', 'https://www.google.ae/maps/place/Al+Barsha+Veterinary+Clinic+llc/@25.113294,55.19448,17z/data=!3m1!4b1!4m2!3m1!1s0x3e5f6bbd63d84bd5:0x84e398c9b4a5a0ff', array['فندق للكلاب والقطط', 'سفر ونقل الحيوانات الأليفة', 'رعاية بيطرية طارئة', 'زيارات بيطرية منزلية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('ABVC - Al Barsha Veterinary Clinic (Kennels & Cattery / Pet Travel)'));
