select 'pets', 'Carry My Pet', 'Carry My Pet', 'دبي', 'القرية الشحنية - مطار دبي', '+97145490495', 'https://www.carrymypet.ae/', null, 'شركة لنقل وسفر الحيوانات الأليفة مقرها القرية الشحنية في مطار دبي.', 'https://www.carrymypet.ae/', 'كاري ماي بت شركة لنقل الحيوانات الأليفة في دبي تقدم النقل من الباب إلى الباب داخليًا ودوليًا. وتذكر أنها أنجزت أكثر من 14,000 عملية نقل وتخدم أكثر من 40 دولة.', 'https://www.carrymypet.ae/assets/images/resources/logo-1.svg', 'sales@carrymypet.ae', 'مكتب 1013، مبنى كارجو ميجا ترمينال، القرية الشحنية، مطار دبي، دبي', null, array['تصدير الحيوانات الأليفة', 'استيراد الحيوانات الأليفة', 'زراعة الشريحة الإلكترونية', 'أقفاص سفر معتمدة من IATA', 'فحص الأجسام المضادة لداء الكلب']::text[], null, true
