select 'pools', 'Pool Masters', 'Pool Masters', 'دبي', 'القوز', '+971 52 993 6776', 'https://poolmasters.ae/', null, 'شركة لإنشاء المسابح وتنظيفها وصيانتها وكشف التسربات، مكتبها الرئيسي في القوز بدبي.', 'https://poolmasters.ae/contact-us/', 'بول ماسترز شركة مكتبها الرئيسي في القوز بدبي ولها فرع في مصفح بأبوظبي. تقدم إنشاء المسابح وتنظيفها وصيانتها وعقود الصيانة السنوية وكشف التسربات وتوريد المعدات.', null, 'info@poolmasters.ae', 'مكتب 203، مبنى سلمان إبراهيم، القوز، دبي', 'https://maps.app.goo.gl/VR7DkHGCMvuigj3U7', array['إنشاء المسابح', 'تنظيف وصيانة المسابح', 'كشف وإصلاح التسربات', 'سخانات ومبردات المسابح', 'عقود الصيانة السنوية']::text[], 'تذكر الشركة أن لديها مختصين معتمدين في كل قسم.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Pool Masters'));
