select 'pools', 'Hydrotech Engineering', 'Hydrotech Engineering', 'الشارقة', 'الصجعة', '+971 6 536 0944', 'https://www.hydrotechuae.com/', 1986, 'شركة هندسية تأسست عام 1986 لإنشاء المسابح والنوافير والمعالم المائية ولها مكتب في الشارقة.', 'https://hydrotechuae.com/Hydrotech-Brochure.pdf', 'تأسست هيدروتك للهندسة عام 1986 ولها مكاتب في أبوظبي ودبي والشارقة وعجمان وقطر. تعمل في تصميم وتنفيذ النوافير الموسيقية والمعالم المائية والمسابح السكنية والتجارية والأولمبية والسبا والساونا، وتذكر أنها الموزع الوحيد في الإمارات لأنظمة توقيت أوميغا ولمسابح ميرثا.', 'https://hydrotechuae.com/wp-content/uploads/2019/02/logo.png', 'sales@hydrotechuae.com', 'ص.ب 33070، الشارقة', null, array['نوافير فيراري وورلد أبوظبي', 'شلال برج خليفة', 'مسابح فندق العنوان دبي مارينا', 'مسبح أولمبي في الشارقة', 'ممشى دبي مارينا']::text[], 'يعمل لدى الشركة أكثر من 300 موظف حسب كتيبها.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Hydrotech Engineering'));
