select 'car_rental', 'Budget Rent A Car – Ras Al Khaimah (AGMC BMW)', 'Budget Rent A Car – Ras Al Khaimah (AGMC BMW)', 'رأس الخيمة', 'الظيت', '+97148735666', 'https://www.budget-uae.com', null, 'فرع بادجت لتأجير السيارات في رأس الخيمة داخل معرض AGMC BMW بمنطقة الظيت.', 'https://www.budget-uae.com/en/our-locations', 'بادجت لتأجير السيارات في الإمارات امتياز لشركة Budget Rent A Car International، وتملكها مجموعة البطحاء للسيارات الشركة القابضة لـ AGMC. توفر الشركة تأجير السيارات والتأجير طويل الأمد عبر فروع في الدولة منها فرع رأس الخيمة.', 'https://www.budget-uae.com/images/budget-logo-img.png', null, 'شارع الشيخ محمد بن سالم، الظيت، رأس الخيمة', 'https://maps.app.goo.gl/es8D7EmGvmD18hub6', array['تأجير السيارات اليومي', 'تأجير السيارات طويل الأمد (Leasing)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'car_rental' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('Budget Rent A Car – Ras Al Khaimah (AGMC BMW)'));
