select 'legal', 'ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah', 'ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah', 'رأس الخيمة', 'المنطقة الحرة لرأس الخيمة (RAKEZ)', '+97172042414', 'https://atblegal.com', null, 'مكتب استشارات قانونية له مكتب في رأس الخيمة يقدم خدمات النزاعات والشركات والملكية الفكرية بين الإمارات والهند.', 'https://atblegal.com/about-us/', 'ATB Legal استشارات قانونية تعمل في القضايا العابرة للحدود والشؤون التجارية بين الإمارات والهند، ولها مكاتب في أبوظبي ورأس الخيمة وبنغالور. تذكر أنها مسجلة أمام محاكم مركز دبي المالي العالمي وسوق أبوظبي العالمي، وتتعاون مع مكاتب إماراتية في قضايا البر الرئيسي.', null, 'offices@atblegal.com', 'مركز الأعمال 04، المنطقة الاقتصادية لرأس الخيمة (راكز)، ص.ب 17212، رأس الخيمة', null, array['تسوية النزاعات والتحكيم', 'قانون العمل', 'الشركات والتجارة', 'الأحوال الشخصية والوصايا', 'الملكية الفكرية والعلامات التجارية']::text[], 'يذكر الموقع أن محاميه يمارسون المهنة منذ نحو عقدين لكلٍّ منهم.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah'));
