select 'engineering', 'Mozoon Engineering Consultancy', 'Mozoon Engineering Consultancy', 'الفجيرة', null, null, 'https://www.mozoonengineering.com', 2000, 'مكتب استشارات هندسية في الفجيرة يعمل منذ عام 2000 في التصميم والإشراف وإدارة المشاريع.', 'https://www.mozoonengineering.com/about.php', 'موزون للاستشارات الهندسية مكتب في قلب الفجيرة بدأ عمله عام 2000، ويقدم المخططات الرئيسية والتصاميم التفصيلية وجداول الكميات وإدارة العطاءات والإشراف على المواقع. يذكر الموقع أن بلدية الفجيرة اختارته أفضل استشاري لعام 2014.', null, null, null, null, array['أكثر من 1500 مشروع منجز بحسب الموقع', 'مبانٍ سكنية وتجارية وفلل', 'مشاريع صناعية وسكن عمال', 'جائزة أفضل استشاري من بلدية الفجيرة 2014']::text[], 'المدير العام ريجي شيريان أسس المكتب في الفجيرة عام 2000.', true
