select 'interior', 'Tech Wood (Tech Group)', 'Tech Wood (Tech Group)', 'عجمان', 'منطقة الجرف الصناعية', '+97167490034', 'https://www.techgroup.ae/tech-wood.html', 2005, 'قسم النجارة والتصميم الداخلي في مجموعة تك بعجمان، يصنّع الأبواب والخزائن والمطابخ والديكورات الخشبية.', 'https://www.techgroup.ae/tech-wood.html', 'تأسست تك وود عام 2005 قسماً لأعمال النجارة والتصميم الداخلي في مجموعة تك. تصنّع وتركّب الأبواب المقاومة للحريق والتكسيات الخشبية وديكورات الفنادق والخزائن والمطابخ وأعمال النجارة للمشاريع التجارية والسكنية.', 'https://www.techgroup.ae/assets/images/logo.png', 'wood@techgroup.ae', 'ص.ب 4048، منطقة الجرف الصناعية، عجمان', null, array['فندق فيرمونت النخلة دبي', 'منتجع وأجنحة رويال أتلانتس', 'مستشفى ثومبي الجامعي – عجمان', 'برج فيجن – عجمان', 'فلل داماك أكويا']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'interior' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Tech Wood (Tech Group)'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'garden', 'Akar Landscaping Services and Agriculture', 'Akar Landscaping Services and Agriculture', 'العين', 'زاخر', null, 'https://www.akarlandscaping.com', null, 'شركة تنسيق حدائق وزراعة في العين، نفذت حديقة دبي ميراكل جاردن.', 'https://www.akarlandscaping.com/', 'عكار لخدمات تنسيق الحدائق والزراعة شركة متخصصة في تصميم وتنفيذ المساحات الخارجية والأعمال الصلبة والمشاتل والعناية بأشجار النخيل. يذكر موقعها أرقاماً قياسية في موسوعة غينيس، منها عرض أُقيم في العين عام 2011.', 'https://www.akarlandscaping.com/assets/img/akar.png', null, 'مبنى رقم 1، شارع 16، مجتمع السويفي، منطقة زاخر، العين', null, array['دبي ميراكل جاردن', 'حديقة الفقع – دبي', 'الحاير – الشارقة', 'أرقام قياسية في موسوعة غينيس (2010 و2011)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'garden' and emirate = 'العين' and lower(coalesce(name_en, name_ar)) = lower('Akar Landscaping Services and Agriculture'));

-- إعادة تفعيل حماية الإغراق
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers enable trigger aq_rate_limit_service_providers;
  end if;
end $$;


-- للتأكد: عدد الشركات في كل قسم وإمارة
select category, emirate, count(*) from public.service_providers where is_active group by 1, 2 order by 1, 3 desc;

